import { Effect } from "effect";
import { Media } from "../../media.js";
import { SpeechAudioDeltaEvent, SpeechFinishEvent, SpeechTimestampsEvent, } from "../../speech.js";
import { concatBytes } from "../../utils/bytes.js";
/** Empty chunks (keep-alive records) emit nothing. */
export const delta = (state, chunk) => {
    if (chunk.length === 0)
        return [state, []];
    state.chunks.push(chunk);
    return [state, [SpeechAudioDeltaEvent.make({ chunk })]];
};
export const step = (onRecord) => (state, frame) => typeof frame === "string" ? onRecord(state, frame) : Effect.succeed(delta(state, frame));
export const timestamps = (texts, starts, ends) => texts.length === 0
    ? []
    : [
        SpeechTimestampsEvent.make({
            items: texts.map((text, index) => ({ text, startSeconds: starts[index] ?? 0, endSeconds: ends[index] ?? 0 })),
        }),
    ];
export const voiceID = (voice) => (typeof voice === "object" ? voice.id : voice);
const CONTAINER_MEDIA_TYPES = {
    mp3: "audio/mpeg",
    wav: "audio/wav",
    opus: "audio/ogg",
    aac: "audio/aac",
    flac: "audio/flac",
};
export const container = (format, sampleRate) => ({
    mediaType: CONTAINER_MEDIA_TYPES[format],
    info: { format, sampleRate },
});
const PCM_MEDIA_TYPES = {
    pcm_s16le: "audio/pcm",
    pcm_f32le: "audio/pcm",
    pcm_mulaw: "audio/mulaw",
    pcm_alaw: "audio/alaw",
};
export const pcm = (encoding, sampleRate, mediaType) => ({
    mediaType: mediaType ?? PCM_MEDIA_TYPES[encoding],
    info: { format: "pcm", encoding, sampleRate, channels: 1 },
});
export const sampleRate = (mediaType) => {
    const rate = /rate=(\d+)/i.exec(mediaType ?? "")?.[1];
    return rate === undefined ? undefined : Number(rate);
};
/** A declared `mediaType` wins over sniffing: headerless PCM can start with bytes that look like an MPEG frame sync. */
export const finish = (route, state, output) => {
    if (state.chunks.length === 0)
        return Effect.fail(route.frameError(`The provider returned no audio${output.detail === undefined ? "" : ` (${output.detail})`}`));
    return Effect.succeed([
        SpeechFinishEvent.make({
            audio: Media.bytes(concatBytes(state.chunks), output.mediaType, { info: output.info }),
            usage: output.usage,
            notices: output.notices,
            providerMetadata: output.providerMetadata,
        }),
    ]);
};
export const headerUsage = (type, value) => {
    const amount = Number(value);
    if (!Number.isFinite(amount))
        return undefined;
    return type === "credits" ? { type, credits: amount } : { type, characters: amount };
};
export * as SpeechStream from "./speech-stream.js";
